insert into public.event_registrations (id, order_id, event_id, studio_id, attendee_first_name, attendee_last_name, attendee_email, status, payment_status, total_price, currency)
values (pg_temp.u('00f1a1'), pg_temp.u('00b0a1'), pg_temp.u('00e002'), pg_temp.u('00a001'), 'Ticket', 'Buyer', 't-r2-t1@example.test', 'confirmed', 'paid', 40, 'USD');
insert into public.event_order_items (id, order_id, event_id, item_type, description, quantity, unit_price, total_price, currency, metadata)
values (pg_temp.u('00c1a1'), pg_temp.u('00b0a1'), pg_temp.u('00e002'), 'ticket', 'GA ticket', 1, 40, 40, 'USD', '{}');
insert into public.event_payments (id, registration_id, amount, currency, payment_method, status, source, stripe_payment_intent_id, stripe_checkout_session_id, stripe_account_id)
values (pg_temp.u('00d0a1'), pg_temp.u('00f1a1'), 40, 'USD', 'card', 'paid', 'stripe', 'pi_r2_t1', 'cs_r2_t1', 'acct_r2test1');

create or replace function pg_temp.pay(p_pi text) returns text language sql stable as $$
  select status::text || '/' || coalesce(refund_amount, 0)::text || '/' || coalesce(stripe_refund_id, '-') from public.event_payments where stripe_payment_intent_id = p_pi $$;
grant execute on function pg_temp.pay(text) to authenticated, anon, service_role;
select pg_temp.chk('G0 baseline: O1 competition payment is paid / 0 / no refund id', pg_temp.pay('pi_r2_o1') = 'paid/0/-', pg_temp.pay('pi_r2_o1'));

-- G1-G3: the old app's direct writes to a competition payment are refused and leave nothing behind
select pg_temp.as_service();
select pg_temp.expect_msg('G1 old webhook, full-refund shape (status refunded, refund_amount = amount, refund id, notes) is refused',
  $q$update public.event_payments set status = 'refunded', refund_amount = 100, refunded_at = now(), stripe_refund_id = 're_old_1', notes = 'Refund synced from Stripe webhook.'
     where stripe_payment_intent_id = 'pi_r2_o1'$q$, 'COMP_REFUND_LEDGER_GATE');
select pg_temp.expect_msg('G2 old webhook, partial pro-rata shape (status paid, refund_amount 27.72) is refused',
  $q$update public.event_payments set status = 'paid', refund_amount = 27.72, refunded_at = now(), stripe_refund_id = 're_old_2', notes = 'Partial refund synced from Stripe webhook.'
     where stripe_payment_intent_id = 'pi_r2_o1'$q$, 'COMP_REFUND_LEDGER_GATE');
select pg_temp.expect_msg('G3 generic staff refund action shape (status refunded, refund_amount, refunded_at) is refused',
  $q$update public.event_payments set status = 'refunded', refund_amount = 100, refunded_at = now() where stripe_payment_intent_id = 'pi_r2_o1'$q$, 'COMP_REFUND_LEDGER_GATE');
select pg_temp.expect_msg('G3b only a refund id (no amount) is refused too',
  $q$update public.event_payments set stripe_refund_id = 're_old_3' where stripe_payment_intent_id = 'pi_r2_o1'$q$, 'COMP_REFUND_LEDGER_GATE');
select pg_temp.expect_msg('G4 insert of an already refunded competition payment row (generic action fallback) is refused',
  $q$insert into public.event_payments (registration_id, amount, currency, payment_method, status, source, stripe_payment_intent_id, refund_amount, refunded_at)
     values (pg_temp.u('00f101'), 100, 'USD', 'other', 'refunded', 'refund', 'pi_r2_o1', 100, now())$q$, 'COMP_REFUND_LEDGER_GATE');
reset role;
select pg_temp.chk('G5 nothing changed after the refusals: payment, order, registration, no ledger or accounting refund rows',
  pg_temp.pay('pi_r2_o1') = 'paid/0/-'
  and (select payment_status from public.event_orders where id = pg_temp.u('00b001')) = 'paid'
  and (select payment_status from public.event_registrations where id = pg_temp.u('00f101')) = 'paid'
  and not exists (select 1 from public.event_order_refunds where order_id = pg_temp.u('00b001'))
  and not exists (select 1 from public.accounting_entries where category = 'competition_entry_refund'));
select pg_temp.expect_ok('G5b a non-refund update of a competition payment (notes) is allowed', $q$update public.event_payments set notes = 'desk note' where stripe_payment_intent_id = 'pi_r2_o1'$q$);

-- G6: non-competition payments are unaffected (same writes the old app performs)
select pg_temp.as_service();
select pg_temp.expect_ok('G6 non-competition payment: old webhook partial refund shape is allowed',
  $q$update public.event_payments set status = 'paid', refund_amount = 10, refunded_at = now(), stripe_refund_id = 're_t_1', notes = 'Partial refund synced from Stripe webhook.'
     where stripe_payment_intent_id = 'pi_r2_t1'$q$);
select pg_temp.expect_ok('G6b non-competition payment: full refund shape is allowed',
  $q$update public.event_payments set status = 'refunded', refund_amount = 40, refunded_at = now(), stripe_refund_id = 're_t_2' where stripe_payment_intent_id = 'pi_r2_t1'$q$);
reset role;
select pg_temp.chk('G6c non-competition payment ends refunded/40.00/re_t_2', pg_temp.pay('pi_r2_t1') = 'refunded/40.00/re_t_2', pg_temp.pay('pi_r2_t1'));

-- G7: the R2 ledger path still works end to end under the gate (request -> pending -> succeeded -> reversal)
select pg_temp.as_user(pg_temp.u('000001'));
insert into t_ids values ('gref1', (pg_temp.request('00b002', '00ab01', jsonb_build_array(pg_temp.line('00c201', 1000, false)))->>'refundId')::uuid);
select pg_temp.as_service();
select pg_temp.chk('G7 observe pending then succeeded applies through the gate',
  pg_temp.observe('pi_r2_o2', 'acct_r2test1', 're_g_1', pg_temp.u('00ab01'), 1000, 'pending')->>'status' = 'pending'
  and pg_temp.observe('pi_r2_o2', 'acct_r2test1', 're_g_1', null, 1000, 'succeeded')->>'outcome' = 'applied');
reset role;
select pg_temp.chk('G7b payment shows the ledger value (paid/10/re_g_1) and the order partially_refunded',
  pg_temp.pay('pi_r2_o2') = 'paid/10.00/re_g_1' and (select payment_status from public.event_orders where id = pg_temp.u('00b002')) = 'partially_refunded', pg_temp.pay('pi_r2_o2'));
select pg_temp.as_service();
select pg_temp.expect_msg('G8 after a ledger refund the old app still cannot write a DIFFERENT amount (pro-rata of the cumulative charge)',
  $q$update public.event_payments set status = 'refunded', refund_amount = 30, refunded_at = now(), stripe_refund_id = 're_old_4' where stripe_payment_intent_id = 'pi_r2_o2'$q$, 'COMP_REFUND_LEDGER_GATE');
select pg_temp.chk('G9 reversal (Stripe reports the refund failed) applies through the gate',
  pg_temp.observe('pi_r2_o2', 'acct_r2test1', 're_g_1', null, 1000, 'failed')->>'outcome' = 'applied');
select pg_temp.keep('gd', pg_temp.observe('pi_r2_o2', 'acct_r2test1', 're_g_d1', null, 3000, 'succeeded'));
reset role;
select pg_temp.chk('G9b reversal restored paid/0 and a dashboard full refund then makes it refunded/30 through the gate',
  pg_temp.out('gd')->>'outcome' = 'applied' and pg_temp.pay('pi_r2_o2') = 'refunded/30.00/re_g_d1'
  and (select payment_status from public.event_orders where id = pg_temp.u('00b002')) = 'refunded', pg_temp.pay('pi_r2_o2'));

-- G10: structure and privileges
select pg_temp.chk('G10 gate triggers exist, are ENABLE ALWAYS, and the gate function is not executable by clients',
  (select count(*) from pg_trigger where tgname in ('r2g_guard_event_payment_refund_upd', 'r2g_guard_event_payment_refund_ins')
     and tgrelid = 'public.event_payments'::regclass and tgenabled = 'A' and not tgisinternal) = 2
  and not has_function_privilege('anon', 'public._r2g_guard_event_payment_refund()', 'EXECUTE')
  and not has_function_privilege('authenticated', 'public._r2g_guard_event_payment_refund()', 'EXECUTE')
  and not has_function_privilege('service_role', 'public._r2g_guard_event_payment_refund()', 'EXECUTE'));

do $$
declare
  v_total int;
  v_failures text;
begin
  select count(*) into v_total from t_results;
  select string_agg(name || ' [' || detail || ']', '; ') into v_failures from t_results where not ok;
  if v_failures is null then
    raise exception 'COMPETITION R2 GATE SQL SUITE PASS (% checks)', v_total;
  end if;
  raise exception 'COMPETITION R2 GATE SQL SUITE FAIL: %', v_failures;
end $$;
